package com.ridex.location.config;
import org.junit.jupiter.api.Test; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.kafka.listener.DeadLetterPublishingRecoverer; import org.springframework.kafka.listener.DefaultErrorHandler; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class KafkaErrorHandlerConfigTest { @Test void createsDeadLetterRecoverer(){KafkaTemplate<String,Object> template=mock(KafkaTemplate.class);assertNotNull(new KafkaErrorHandlerConfig().deadLetterPublishingRecoverer(template));} @Test void createsErrorHandler(){KafkaTemplate<String,Object> template=mock(KafkaTemplate.class);var recoverer=new KafkaErrorHandlerConfig().deadLetterPublishingRecoverer(template);DefaultErrorHandler handler=new KafkaErrorHandlerConfig().kafkaErrorHandler(recoverer);assertNotNull(handler);} }
